fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    // Lower-bound binary search: first index i such that arr[i] >= target.
    let mut lo: usize = 0;
    let mut hi: usize = arr.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}